    minimum_slope_atr: float = config_field(0.02, canonical_env='TL_MIN_SLOPE_ATR', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.ATR, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Minimum |slope| in ATR/bar; resistance must fall, support must rise.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 0.02),), validation_summary='Pydantic type coercion + model validator')
    maximum_slope_atr: float = config_field(0.15, canonical_env='TL_MAX_SLOPE_ATR', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.ATR, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Maximum |slope| in ATR/bar.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 0.15),), validation_summary='Pydantic type coercion + model validator')
    minimum_touches: int = config_field(3, canonical_env='TL_MIN_TOUCHES', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.COUNT, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Minimum counted touches after spacing collapse.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 3),), validation_summary='Pydantic type coercion + model validator')
    maximum_touches: int = config_field(4, canonical_env='TL_MAX_TOUCHES', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.COUNT, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Touches at or above this mark the line exhausted (still constructed).', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 4),), validation_summary='Pydantic type coercion + model validator')
    minimum_span_bars: int = config_field(20, canonical_env='TL_MIN_SPAN_BARS', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.COUNT, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Minimum bars between first and last counted touch.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 20),), validation_summary='Pydantic required/type coercion only')
    minimum_touch_spacing_bars: int = config_field(3, canonical_env='TL_MIN_TOUCH_SPACING', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.COUNT, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Collapse touch clusters closer than this spacing (keep earliest).', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 3),), validation_summary='Pydantic required/type coercion only')
    maximum_bars_since_last_touch: int = config_field(30, canonical_env='TL_MAX_BARS_SINCE_TOUCH', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.COUNT, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Reject lines whose last touch is older than this many bars.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 30),), validation_summary='Pydantic required/type coercion only')
    maximum_fit_error_atr: float = config_field(0.15, canonical_env='TL_MAX_FIT_ERROR_ATR', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.ATR, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Maximum mean touch residual in ATR.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 0.15),), validation_summary='Pydantic required/type coercion only')
    maximum_violations: int = config_field(2, canonical_env='TL_MAX_VIOLATIONS', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.COUNT, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Maximum wick pierces without close-through.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 2),), validation_summary='Pydantic required/type coercion only')

    @model_validator(mode='after')
    def validate_trendline_bounds(self):
        if not self.minimum_slope_atr < self.maximum_slope_atr:
            raise ValueError('minimum_slope_atr must be < maximum_slope_atr')
        if self.minimum_touches > self.maximum_touches:
            raise ValueError('minimum_touches must be <= maximum_touches')
        return self

